## 七、三层认知模型（贯穿 P0-P2）

在 P0→P1→P2 的全流程中，保持以下认知引导模型：

```
P0: 我的故事是什么？（方向确认 → 用户建立了表达欲）
P1: 我写出来的东西……好像和我想的不一样？（暴露差距 → 用户自己发现了问题）
Layer 2: 原来我练这个是因为……（理解训练目的 → 用户有参与感）
P2: 我来试试看能不能改好（执行训练 → 用户有自主感）
```

**每一层都让用户"自己往前走一步"，而不是被推着走。**''',
);

const Skill _narrativeDesign = Skill(
  meta: SkillMeta(
    id: 'narrative-design',
    group: 'teaching',
    estimatedTokens: 3800,
  ),
  content: '''# SKILL: 叙事设计引导

> **定位**: 教练如何通过提问帮用户**构建**世界观和角色——不是诊断已有文本的问题，而是帮用户从模糊想法变成可落地的设计。
> **与 coaching-rhythm 的分工**: coaching-rhythm 管"对话节奏"（先问什么后问什么），本 skill 管"对话内容"（每个方向应该问什么、追多深、怎么收）。
> **loadWhen**: P0（从零构建）/ P1（世界观阶段）/ P2（诊断中发现设计层面问题时回退）
> **体积**: 约 3800 tokens

---

## 一、定位与激活条件

### 1.1 什么时候用本 skill

本 skill 提供**设计层面的引导方法论**。当以下任一信号出现时激活：

| 信号 | 含义 |
|------|------|
| 用户在"从零构建"中选择了"从角色开始" | → 使用 §三（角色构建引导） |
| 用户在"从零构建"中选择了"从世界观开始" | → 使用 §二（世界观构建引导） |
| 用户展示的文本暴露出**设计层面**的问题（角色动机模糊、世界观碎片化） | → 使用对应章节帮用户回到设计层面重新理清 |
| 用户完成了第一步写作后来讨论角色/世界观 | → 使用 §五（世界观与角色交织） |
| P1_WORLD 阶段用户有文本但需要深化设计 | → 使用对应章节 |

### 1.2 不用本 skill 的场景

- 用户正在做生成式写作练习（N0-N2 elementary 练习）→ 用 beginner-path.ts
- 用户文本已有明确症候且正在训练中（P2 PRACTICE）→ 用 technique-library + coaching-actions
- 用户已经在执行具体写作动作 → 不打断

### 1.3 核心哲学

设计引导 ≠ 教你怎么写设定。设计引导 = 通过提问帮用户：
1. **发现**自己真正想表达的核心
2. **选择**（放弃也是一种设计）
3. **一致化**（不同设定之间的逻辑自洽）
4. **降维**到可执行的写作目标

与文本技巧的最大区别：技巧是"这句话怎么改"，设计是"这个世界为什么要这样"。

---

## 二、世界观构建引导

### 2.1 五层递进提问框架

不要一次性全问。根据用户的回答深度逐层推进。每层用户回应后才进下一层。

#### 第一层：核心差异（必问）

**目的**: 帮用户找到这个世界的"一句话定义"——它和我们现实世界最大的不同是什么。

**提问**（选 1-2 个）：
> "如果用一个词描述你这个世界和现实世界最大的不同，会是什么？"
> "在这个世界里，有什么事情是可能发生但在现实里绝对不可能的？"
> "这个世界的居民最习以为常、但读者会感到惊讶的一件事是什么？"

**完成标志**: 用户能说出一句话级别的核心差异

**红线**: 
- ❌ 不要问"魔法体系是怎样的"——那是第二层的问题
- ❌ 不要接受"奇幻世界""废土世界"等类型标签作为答案——追问"这个奇幻世界和别的奇幻世界有什么不一样？"

#### 第二层：运作逻辑（用户回应第一层后可选）

**目的**: 核心差异如何在日常生活中运作。

**适用判断**: 如果用户的第一层回答需要展开（如"这里的人出生就带着一种天赋"），才进入第二层。

**提问**（只追问用户已经提到的维度）：
> "你提到了天赋系统——这种天赋是怎么影响日常生活的？拥有不同天赋的人，在街上相遇会怎样？"
> "这个规则影响最大的不是英雄——是最普通的居民。一个普通人怎么在这个规则下活一天？"

**追问原则**: 不问"为什么"——只问"怎么体现"。世界观规则的可信度不在解释，在**日常细节中的倒影**。

**完成标志**: 用户讲出了一个具体的生活场景（不是设定说明，是画面）

#### 第三层：社会结构（用户有多个势力/群体时可选）

**适用判断**: 用户提到"国家""宗派""阵营""种族"等复数群体时才进入。

**提问**（选一个）：
> "这些群体之间的关系，核心冲突是什么？——不是战争的理由，是**为什么必须对立**。"
> "有没有一个群体，读者一开始以为它是反派，但实际上它的逻辑是对的？"

**红线**: 不要让用户列"三大宗派五大王国"的清单——那不是设计，是填表。只追问冲突和不均衡。

#### 第四层：环境影响（用户开始写场景后可选）

**适用判断**: 用户已开始写作但场景氛围感不足时激活。此时不回到第一层重新设计，而是追问已有设定如何体现在场景中。

**提问**：
> "你说这个世界总是下雨——你刚才写的这场对话，他们是在屋檐下还是淋着雨说的？"
> "这个世界最日常的交通工具是什么？你刚才的场景里角色是怎么移动的？"

#### 第五层：收敛（必须）

**目的**: 确保用户不会无限扩展世界观。设计越多，下笔越难。

**触发**: 用户在世界观讨论中已经超过 3 轮对话（不含第五层本身）。

**话术**：
> "够了。你已经有了核心规则、一个日常场景、一组冲突群体。现在来看你已经有的东西，选一个——哪个设定对你的第一个故事最重要？其他的可以以后再展开。"
> "记住：读者不需要在第一章了解这个世界的一切。读者只需要在第一段被一个画面抓住。"

### 2.2 世界观常见陷阱（教练识别 + 引导）

| 陷阱 | 信号 | 引导方向 |
|------|------|---------|
| **设定膨胀** | 用户说的设定越来越多，但没有落地到任何一个场景 | 选一个设定，问"这个设定下，一个普通人今天下午三点在做什么？" |
| **为奇而奇** | 设定的唯一功能是"很酷" | 问"这个设定的存在，对你主角的困境有什么影响？"→ 如果没有影响 → "要不要先保留这个想法，先聚焦对主角有影响的设定？" |
| **只建不拆** | 用户建了庞大世界观但不选重点 | 问"如果你的小说只能保留这个世界观的三样东西，你保留哪三样？" |
| **替代写作** | 用户在不断设计世界观但就是不动笔写正文 | 第五层收敛后直接过渡到 coaching-rhythm 第四步"第一阶段优先" |

---

## 三、角色构建引导

### 3.1 四层递进提问框架

#### 第一层：欲望与恐惧（必问）

**目的**: 这是角色的发动机。没有这二者，角色只是名字+外貌。

**提问**（两个都必须触及）：
> "你的主角最想要什么？——不是大结局要达到什么，是**现在**最想要什么。"
> "他最怕的又是什么？——不是客观危险，是他内心最恐惧的东西。"

**追问**（如果用户回答模糊）：
> "他想要的东西，为什么现在得不到？如果很容易得到，故事就结束了——什么东西在阻止他？"
> "他最怕的东西——他有没有试着掩饰这种恐惧？怎么掩饰的？"

**完成标志**: 用户能说出"主角想要 X，但被 Y 阻止。同时他最怕 Z，所以他用 W 来掩饰。"

#### 第二层：缺陷与弧光（用户回应第一层后）

**目的**: 角色的缺陷是什么——不是"脾气不好"这种标签式缺陷，而是**导致他没有得到想要的东西的本质原因**。

**提问**（核心一问）：
> "你刚才说他想要 X 但被 Y 阻止。但 Y 是外部障碍，对吧？他最想要的东西，有没有一个原因是**他自己**造成的？他性格里什么让他得不到？"
> "故事结束时，他会变成什么样的人？——不是获得什么，是**变成什么**。"

**红线**: 
- ❌ 不要接受"他太善良"作为缺陷——那是伪缺陷，是优点的另一种说法
- ❌ 不要替用户设计弧光——问方向，让用户自己找到转折点
- ✅ 用户的回答可以是"他需要学会信任别人"或"他需要接受自己的平凡"

#### 第三层：日常质感（用户准备开始写时可激活）

**目的**: 让角色从"设计文档"变成"活人"——不是问大背景，是问日常细节。

**提问**（选 1-2 个，不要全部问）：
> "他早上醒来做的第一件事是什么？——不是重要的仪式，是下意识的动作。"
> "他吃早饭的时候是一个人还是和别人一起？吃的时候在想什么？"
> "他走在街上的时候——别人看他的第一眼会注意到什么？他自己知道吗？"
> "他有什么小习惯是周围人觉得奇怪但他自己习以为常的？"

**哲学**: 角色的真实性不是靠"背景故事"建立的，是靠**读者能具体想象的日常画面**建立的。

#### 第四层：收束（必须）

**目的**: 确保角色设计能驱动叙事。不能驱动叙事的角色设计是无效设计。

**话术**：
> "好了。现在用一句话说：**这个主角在第一幕的状态是什么？**"
> "——不是他的性格，不是他的身份。是他故事开始时的**处境**：他在哪里，他和谁在一起，他遇到了什么问题。"
> "这就是第一章的第一句话应该承接的东西。"

### 3.2 角色常见陷阱

| 陷阱 | 信号 | 引导方向 |
|------|------|---------|
| **角色空心** | 用户能说出主角外貌、身份、背景，但说不出"他想要什么" | 跳回第一层，追问欲望 |
| **弧光缺失** | 角色从开始到结束没有变化 | 问"故事结束时，他有什么事情做不到了/不做了/开始做了——这些是故事开始时他完全不会的" |
| **功能化角色** | 配角只是"推动情节"的工具 | 问"这个配角——除了推动情节，他自己想要什么？他跟主角的目标有什么冲突？" |
| **自传体主角** | 主角=作者理想化形象，没有缺陷 | 问"如果去掉所有优点，你的主角还有什么是让读者想看他继续走下去的？"（如果用户答不上来 → 角色需要缺陷） |

---

## 四、配角功能分类与关系张力

### 4.1 配角不是"重要程度"分类

配角的设计核心不是"戏份多少"，而是**和主角形成什么功能关系**。

| 功能类型 | 定义 | 提问方式 |
|---------|------|---------|
| **盟友** | 和主角目标一致但**方法不同** | "这个人和主角想要的是同一件事吗？如果是，他们的路线有什么分歧？" |
| **对手** | 和主角目标冲突，但**有自己的正当理由** | "这个对手——他的理由是什么？如果从他的角度看，他在做的事情也是对的，对在哪？" |
| **镜像** | 和主角相似但做了**不同选择**的人（"他本可能变成的样子"） | "有没有一个角色，他的人生轨迹和主角几乎一样，但他在某个岔路口选了不同的路？" |
| **催化剂** | 不是主角团成员，但其**存在本身**改变了主角的选择 | "有没有一个人——他不需要做任何事，但只要他存在，主角的行为就会不同？" |

### 4.2 关系张力网络（选问）

**适用**: 用户已经设计了 3+ 个角色。

**目的**: 角色之间不只有"好/坏"关系。最精彩的张力来自**不纯粹的冲突**。

**提问框架**（选一组关系最模糊的角色来问）：
> "角色 A 和角色 B——他们现在的关系是什么？"
> "有一件事情是 A 知道但 B 不知道的，是什么？反过来呢？"
> "如果有一天 A 做了一件事，让 B 觉得'我以为自己了解他，但我完全不了解'——这件事可能是什么？"
> "在故事的中段，他们的关系会发生什么变化——不是因为外部事件，是因为**彼此**的改变？"

**完成标志**: 用户讲出至少一对角色之间的"不对称"关系——不是平等的关系，不是纯粹的爱/恨。

---

## 五、世界观与角色的交织

### 5.1 这是设计层面最容易断裂的地方

世界观和角色分别设计好了——但它们是**两张拼不上的拼图**。

教练需要检测这个断裂并引导缝合。

### 5.2 交织检测三问

当用户展示了一段文本（包含设定+角色行为），依次检查：

**问题 1: 角色承载世界观吗？**
> "这个世界的核心规则，对你主角的日常生活有什么影响？如果规则变了，主角的行为会变吗？"
> 如果答"不会变" → 世界观和主角是**分离的**。设定没有进入角色的血液。

**问题 2: 世界观塑造角色吗？**
> "这个世界最残酷/最特别的地方，在你主角身上留下了什么痕迹？不是伤疤——是**习惯**。他有什么习惯是这个世界的规则逼出来的？"
> 如果用户想不出来 → 世界观是**背景板**，不是角色的塑造者。

**问题 3: 角色改变世界吗？**
> "你的主角在这个世界的规则下活了一辈子。他有没有**对抗过**这个世界的规则？哪怕只是很小的一次？"
> 如果用户说"没有"或"还没写到"→ 这是一个叙事潜力信号。记录下来，对用户说："这个我们留着，写到中间阶段的时候会很重要。"

### 5.3 缝合引导

当检测到断裂时（上述任一问题用户无法回答），使用以下引导：

> "你说这个世界的魔法需要付出代价——对你主角来说，他**已经**付出了什么代价？他每天因为这条规则要做什么选择？"

原则：**不从设定讲设定——从角色的日常选择反推设定如何落地。**

---

## 六、教练引导流程（与 coaching-rhythm 的衔接）

### 6.1 触发时机映射

| coaching-rhythm 的阶段 | 本 skill 对应做什么 |
|------------------------|-------------------|
| 第一步：方向确认 | 不介入（用户还没选定方向） |
| 第二步：重心选择（用户选"从角色开始"） | 激活 §三 第一层（欲望与恐惧） |
| 第二步：重心选择（用户选"从世界观开始"） | 激活 §二 第一层（核心差异） |
| 第三步：WHO/WHAT/WHY | WHO → 追 §三 第一层（如果还没追过）；WHAT → 收束到场景；WHY → 追到角色缺陷层 |
| 第四步：第一阶段优先 | 本 skill 收束——确保设计已收敛，不再展开 |

### 6.2 追问的深度控制

关键原则：**每层只进一层，不连续跳**。

- 用户回答了第一层（如"主角最想要复仇"）→ 可以进第二层追问"那他自己有什么在阻止他？"
- 用户在第二层回答了缺陷 → 暂停！先不要进第三层。让用户先去写一段，看看这个缺陷在文字里怎么体现。
- 用户写完回来讨论 → 激活第三层"日常质感"和 §五"交织检测"

**信号判断**：
- 用户回答越来越短、越来越模糊 → 收住，不要再追。给一个写作目标，让用户先去写。
- 用户回答越来越长、越来越兴奋 → 可以继续追一层，但仍不要连跳。

### 6.3 从零构建→P1 的过渡

当用户通过从零构建产出了第一段（≥100 字）文本后：
- coaching-rhythm 结束从零构建模式
- 如果有角色/世界观设计上的明显问题 → 本 skill 仍然活跃，用 §二-§五 引导
- 如果问题主要是文本层面的（句式、描写等）→ 本 skill 退场，由 diagnosis 体系接手

---

## 七、常见组合场景

### 场景 1: 用户有了角色但世界观空白

> "不用急着构建整个世界。你的主角活在哪个时代/环境里——最简单的回答：他是用手机还是用剑？他出门靠走的还是坐飞行器？他在的世界，有没有一条规则让他的日常生活和我们的不同？先回答这个就行。"

### 场景 2: 用户有了世界观但角色像工具人

> "你这个世界的规则我已经了解了。现在问一个关键问题：有一个人，他**不适应**这个世界的规则。他是谁？他哪里不适应？"
> 设计铁律：完全适应世界规则的角色没有叙事张力。主角总是在某个维度上"不合时宜"。

### 场景 3: 用户想同时展开所有设计方向

> "我理解你的热情。但设计有一个铁律：**你不需要在今天决定一切**。你只需要决定——这个故事的第一章，读者需要知道哪三件事。其余的设计，留着，在需要的时候自然浮出来。"
> 然后帮用户选三件事：一个核心规则 + 一个角色处境 + 一个即时事件。

### 场景 4: 用户卡在设计里出不来（"分析瘫痪"）

> "你已经想了很多了。现在，关掉设计文档。我们做一个实验：你从你已经想好的设定里，**扔掉**80%。保留最核心的 20%——然后写一段。"
> "写完之后你会发现，那 80% 并没有消失。它们会在你不需要'想'的时候自己冒出来。"''',
);

const Skill _plotDesign = Skill(
  meta: SkillMeta(id: 'plot-design', group: 'teaching', estimatedTokens: 3400),
  content: '''# SKILL: 情节与结构设计引导

> **定位**: 教练如何通过提问帮用户**构建故事的情节与结构**——叙事铁三角的第三角（世界观 / 角色 / 情节）。
> **与 narrative-design 的分工**: narrative-design 管"这个世界是什么样的 + 谁活在其中"，本 skill 管"现在这些人要做一件什么事——事情怎么开始、怎么发展、怎么结束"。
> **loadWhen**: P0（从零构建选了方向后）/ P1（世界观阶段需要故事引擎）/ P2（诊断发现结构性问题时回退到设计层）
> **体积**: 约 3400 tokens

