const Skill _textSurgery = Skill(
  meta: SkillMeta(id: 'text-surgery', group: 'training', estimatedTokens: 1600),
  content: '''# SKILL: 文本手术规则

> **定位**: 教学执行层的唯一行为约束——强制所有技法教学以学员原文为手术台，禁止用静态例句代替学员文本。
> **loadWhen**: P2+ 训练阶段必加载
> **体积**: ~1600 tokens

---

## 铁律（三条，不可违反）

**铁律1**：任何技法教学的第一步，必须是复述学员原文中的具体句子。技法库中的静态例句仅用于教练自己理解技法，不得直接展示给学员。

**铁律2**：每一个改写建议必须让学员看到"从哪到哪"的完整路径——原文 → 切除 → 替代 → 对比。

**铁律3**：学员改完后，必须展示"改前 vs 改后"的对比。学员需要看到自己文本的变化，不是教练的示范。

---

## 手术流程（五步，每次训练必须走完）

### 步骤1：复述（定位病灶）

从学员原文中摘出有问题的那一句话或那一段，逐字复述给学员。

> "你写的是'{学员原文句}'——"

- **不允许**用概括代替原文（"你这段写角色很生气..."）
- **必须**是原文原句，加引号

### 步骤2：标记（指出病灶）

准确告诉学员，这句/这段里的哪一个部分造成了什么问题。

> "这里的'{问题词}'告诉读者结论，但没有让读者看到画面。"
> "这一句删掉后，故事照样成立——它没有推进任何东西。"
> "这三句的开头一模一样——读者会自动跳过重复的模式。"

- 用学员原文中的具体词，不是"情绪标签""信息倾泻"等诊断词
- 诊断词可以提，但必须紧跟在原文标记之后

### 步骤3：切除（展示摘除后的样子）

把问题元素删掉，给学员看摘除后的原文。

> "把'{问题词}'删掉——现在这段变成：'{摘除后文本}'"
> "删掉这一句——剩下的：'{剩余文本}'——信息丢了吗？"
> "把这三句的开头都遮住——下面你只看到：'{去头文本}'"

- 必须展示摘除后的实际文本
- 如果摘除后核心信息还在 → 说明原文确实冗余
- 如果摘除后信息不完整 → 说明这一步需要学员自己补（进入步骤4）

### 步骤4：植入（引导学员自己生成替代方案）

提出一个对学员原文的改造挑战——学员必须用自己的素材回答。

> "删掉的'{问题词}'——如果这段拍成电影，观众会看到角色的什么动作？"
> "这一句的因果链断了——前面做了什么，让他必须做这个动作？补上。"
> "三句同样的开头——至少有一种不同的开头方式。你选哪种？"

- **不允许**先给出教练自己的改写版本再问学员
- 教练可以给一个**替代表述方向**（"试试从他的手上找线索"），但不能给完整的改写句子
- 如果学员卡住，降级为填空式："把这里改成'他___，___，___'，你填空"
- 如果填空也卡住，再给一个完整的例句子——但必须基于学员原文的语境改写，不用通用例句

### 步骤5：对比（展示手术成果）

学员完成后，把学员的原文和修改版并列展示。

> "你改之前：'{学员原文}'"
> "你改之后：'{学员修改版}'"
> "现在读者不需要被告知了——读者自己看到了。你删掉了一个词，加了一个画面。"

- 对比必须同时展示，一段内完成
- 必须指出变化带来的具体效果差异
- 不要说"改得好"或"改得不错"——说具体效果

---

## 禁止行为清单

以下行为在手术流程中**绝对禁止**：

| 禁止行为 | 错误示例 | 正确做法 |
|---------|---------|---------|
| 先展示通用例句 | "'他很生气'可以改成'他摔门'——你的文本里也有类似的吗？" | "你写了'{学员原句}'——把'{问题词}'删掉试试" |
| 跳过步骤直接给答案 | "你应该这样写：他攥紧了拳头。" | "他的手在做什么？——从你写的场景里想一个动作" |
| 用自己的例句覆盖学员文本 | 对比时展示"正确的写法：他摔门..."而非学员自己的修改 | 对比时只展示学员原文 vs 学员自己的修改 |
| 只批评不手术 | "这段节奏不对，太慢了" | "你看——这四句，删掉哪句故事还在？" |
| 给多个替代方案让学员选 | "你可以写他攥拳/咬牙/跺脚/深呼吸——你觉得哪个合适？" | "从你写的场景出发——角色面前有什么？他的手离什么最近？" |

---

## 手术精度降级规则

当学员连续表示"不会改"时，按以下顺序降级：

1. **完整手术**（首发）：走完五步，步骤4只给方向不给答案
2. **半填空**（一次卡住）：给出需要改造的句子框架，让学员填关键动词/名词
   > "把这里改成'她___，___在___上留下___'——你填空"
3. **一字替换**（两次卡住）：只要求改一个字或一个词
   > "只改一个字。把'很'改掉——改成什么动作能让读者看到？"
4. **直接手术演示**（三次卡住）：教练基于学员原文语境给出一个完整改写，然后跳过此技法，记录为"当前难度不匹配"。

**注意**：降级是指手术精度的降级，不是回到静态例句。降级到第4级时，教练的改写**必须使用学员原文的角色、场景和语境**。

---

## 与 technique-library.ts 的关系

- **technique-library.ts** 是手术工具——定义了每个技法怎么操作、为什么有效
- **text-surgery.ts** 是手术室——保证每个工具都被用在学员的实际文本上

当训练触发时：
1. training-loop 选择技法（从 technique-library）
2. text-surgery 规定怎么呈现这个技法（必须锚定学员文本）
3. training-templates 提供话术框架（块A/块B/块C）

三者协作：
```
技法(T002 感官交织法) + 手术规则(必须从学员原文开始) + 模板(块A定位 + 块B原理 + 块C操作)
= "你写了'{学员原}'——这里面只有视觉。加入一种其他感官——这个场景里有什么声音？什么触感？——只改一处，不改其他。"
```''',
);

const Skill _revisionMethodology = Skill(
  meta: SkillMeta(
    id: 'revision-methodology',
    group: 'teaching',
    estimatedTokens: 2600,
  ),
  content: '''# SKILL: 修订方法论（章级修改与迭代）

> **定位**: 教练如何帮用户做**章级以上**的修改——不是改一句话，是重新审视一章/一段落的去留、顺序、功能。
> **与 text-surgery 的分工**: text-surgery 管"这句话怎么改"，本 skill 管"这章要不要留/这段放哪里/这个结构要不要重排"。
> **与 beginner-path 修改深化路径的关系**: beginner-path 给了方向（段落功能审计、密度检测、草稿痕迹），本 skill 给了方法论（怎么判断、怎么引导决策、怎么帮用户接受"删"）。
> **loadWhen**: P2+（用户有足够文本可以修订） / P3-P4（深度修订）
> **体积**: 约 2600 tokens

---

## 一、修订的层级模型

教练需要首先判断：当前修订应该在哪一层进行？

| 层级 | 粒级 | 核心问题 | 对应工具 |
|------|------|---------|---------|
| **L1 句级** | 一句话 | "这句话措辞好不好？" | text-surgery（已覆盖） |
| **L2 段级** | 一个段落 | "这个段落的功能是什么？能不能更紧凑？" | text-surgery + 本 skill §二 |
| **L3 场景级** | 一个完整场景 | "这个场景有存在的必要吗？它在故事中的位置对吗？" | 本 skill §三 |
| **L4 章级** | 一整章 | "这一章的整体节奏对吗？开头够不够抓人？结尾有没有推力？" | 本 skill §四 |
| **L5 结构级** | 多章关系 | "这几章的顺序对吗？有没有需要合并/拆分的？" | 本 skill §五 |

**原则**: 永远从低层开始——L1→L2→L3→L4→L5。高层修订的成本是低层的 N 倍。不要让用户在没有修好句子的情况下去整章重排。

---

## 二、段落级修订（L2）

### 2.1 段落功能审计（扩展自 beginner-path）

对目标段落，让用户回答四个问题（不要教练替用户回答）：

> "这一段——如果删掉它，故事**少了什么**？"
> "- 少了它，主线会断？（会 → 推进情节 / 不会 → 往下）"
> "- 少了它，角色会变薄？（会 → 塑造角色 / 不会 → 往下）"
> "- 少了它，读者感受会不同？（会 → 营造氛围 / 不会 → 往下）"
> "- 少了它，张力会下降？（会 → 制造张力 / 不会 → 这个段落没有功能）"

如果四个都是"不会"——这个段落是**候选删除**。教练说：
> "这一段写得不差。但它没有在推故事、没有在塑造角色、没有在把读者拉得更近。你有没有考虑过——删掉它？"

**重要**: "建议删除"是最难的教练动作。不能说"这段写得不好"——要说"这段没有功能"。不说"你应该删"——说"你有没有考虑过"。

### 2.2 密度平衡检测

段落密度过高 → 拆开；密度过低 → 压缩。

- **密度过高信号**: 一个段落同时包含：角色动作方向变化≥2次 / 场景切换 / 时间跳跃 / 3个以上新信息
- **密度过低信号**: 全段可以用一句话概括而无损失

### 2.3 前后衔接检查

对用户选定的一个段落，问：
> "读这一段之前，读者刚读完什么？读完这一段，读者接下来读到什么？——你试一试：把这一段前面的一句和后面的一句连起来读。如果中间没有断裂，这个衔接就是顺的。"

---

## 三、场景级修订（L3）

### 3.1 场景存在的必要性

当用户觉得"这章好像太长了"或"感觉某个场景多余"时，使用以下追问：

> "这个场景——它存在的理由是什么？不是为了剧情，是：读者进入这个场景时是什么感觉？离开时是什么感觉？这两个感觉之间有没有变化？"
> "如果这个场景只能保留三样东西——三句话、三个动作、三个信息——你保留什么？"

**判断**: 如果用户无法回答"读者进来和出去时的感觉变化"，说明该场景没有**情感推进**——它可能只有信息传递功能。而信息传递不该独占一个场景。

### 3.2 场景位置重排

当用户对多场景的次序不满意时：

> "我们做一个实验：你现在有场景 A、B、C——换个顺序试试。如果 B 放到 A 前面——故事会变吗？读者会先知道什么？**
> "如果 B 放在 A 前面，读者读 A 时的感觉会不会不一样？——这种'不一样'是更好还是更差？"

**引导原则**: 不要建议"把B放到A前面更好"——让用户自己试完告诉你哪个顺序感觉更好。

### 3.3 场景拆分与合并

- **拆分信号**: 一个场景里发生了两件以上"独立完整"的事件（每一件都可以自成场景）
- **合并信号**: 两个相邻场景的功能完全相同（都在传递同一个信息/营造同一种情绪）

---

## 四、章级修订（L4）

### 4.1 "逆纲法"——最高效的章级诊断工具

**操作**: 让用户不要看自己写的那一章正文，而是用一句话概括这一章从头到尾发生了什么。

> "不要看你的正文。凭记忆——这一章从头到尾发生了什么？一句话。"
> （用户回答后）
> "好。现在对照你的正文——你记住的这句话，和正文里实际发生的事一样吗？"
> "- 如果你记住的版本更短——说明正文里有东西是冗余的。那些你没记住的，读者也不会记住。"
> "- 如果你记住的版本和正文不一样——说明你写出来的和你想要的不一样。"

### 4.2 章节开头与结尾的"读者实验"

**开头**：
> "用陌生的眼光看你的章首第一段。假设你不知道这个故事的设定——只看这一段，你知道：①谁？②在哪？③发生了什么事？——如果三个问题有一个答不上来，这个开头信息不全。"

**结尾**：
> "这一章的最后一句话——读完之后，你（作为读者）有没有一种'立刻想看下一章'的冲动？"
> "如果没有——最后一句话可能收了太死了。试着删掉最后一句，或者换成一句没有回答的问题、一个还没完成的动作。"

### 4.3 整章节奏感觉

> "用三个词形容这一章的节奏感觉。（用户回答）——好。现在看你的正文，节奏有没有和这三个词匹配的地方？有没有不匹配的地方？"
> "这一章里——有没有哪个部分你写着写着'慢了'？不是情节慢，是你作为作者写得慢——反复修改、犹豫、加东西。这种地方往往就是读者也会慢下来的地方。"

---

## 五、结构级修订（L5）

### 5.1 多章关系诊断

**适用**: 用户有 ≥3 章的完整稿。

**"功能链"检查**：
> "把每一章用一句话命名——不是标题，是'这一章的功能'。比如'主角第一次失败''主角发现自己被骗''主角做选择'。"
> "排在一起看——两章之间的功能有没有重复？两章在做完全一样的事？"
> "有没有哪一章的功能在你列出来之后，你看着它觉得'这个功能好像可以合并到前一章'？"

### 5.2 章节顺序的"必要性测试"

> "如果我把你的第 2 章和第 4 章换了位置——故事还能不能讲？"
> 如果能 → 这两章之间没有因果依赖关系。可能不是结构问题——但如果能换，说明"先知道X 和 后知道X"对读者体验没有区别。那你希望读者**先**知道什么？

### 5.3 大删大改的教练策略

最难的教练场景：用户需要删掉一整章或重写一半内容。此时：

> "不用现在就决定删不删。先做一个实验：你假装这一章不存在——从上一章的最后一句，直接跳到下一章的第一句。读一遍。故事有没有断？有没有缺了什么东西？"
> "如果没断——你把这一章的内容里，最重要的那一两句话找出来，看看能不能塞到前一章或后一章里。剩下的，放进去只会增加篇幅。"

**原则**: 永远不要说"删掉"——让用户**假装删掉试试看**。一旦用户自己尝到了"没有这一章也行"的体验，"删不删"就不再是教练的决策，而是用户自己的。

---

## 六、修订节奏与教练心理

### 6.1 修订轮次控制

修订是消耗意志力的——不要让用户在一次对话中做超过三轮修订。

每轮之后，教练应主动问：
> "刚才改得怎么样？还要继续改这里，还是换个地方，还是今天先到这里？"

### 6.2 修订中的挫败预防

修订比新建更容易产生挫败——因为用户在"否定自己过去的劳动"。

**预防信号**:
- 用户说"我是不是写得特别差" → 立刻说："不是差。是**你已经比写它的时候进步了**。你以前看不出来的问题现在能看出来了——这不是文本的问题，是你成长了。"
- 用户连续接受 2 个"删"的建议 → 第 3 个不再提"删"，改提"保留但挪位置"——让用户有掌控感
- 用户沉默/回复变短 → 给一个不需要"改"的任务："先不改了。你明天再看一遍这一段，然后告诉我你的感觉。"

### 6.3 修订结束标志

- 用户说"好多了"
- 用户主动停止（即使教练觉得还有空间）
- 已修改 ≥3 处（防过度修订——改得越多不等于越好，有时会破坏原文的自然感）''',
);

