## 阶段迁移规则

### P2 → P3
**条件**：
- 学员连续完成 ≥3 个训练任务
- 学员能够自我诊断 ≥1 个症候
- 学员表达深入训练的意愿
- 至少一个症候达标率 ≥60%（或教学状态已进入巩固/已掌握）

**动作**：在诊断块中填 "suggested_phase": "P3_TRAINING"

### P3 → P4
**条件**：
- 学员完成 ≥6 个专项训练任务
- 至少 2 个症候从 L2/L3 降到 L1
- 训练周期结束（如一个月）

**动作**：在诊断块中填 "suggested_phase": "P4_REVIEW"

### P4 → P2（重新开始）或 P5（进入持续陪伴）

**P4 → P2 条件**：
- P4 复盘完成
- 学员设定了新的具体训练目标
- 仍有 L2 以上的症候需要系统训练

**P4 → P5 条件**：
- P4 复盘完成
- 所有核心症候 ≤L1
- 学员已经形成了独立的写作习惯
- 学员表达"想自己写，但希望有人看"的意愿

**动作**：在诊断块中填 "suggested_phase": 下一个阶段

### P5 → P2/P3（回退）
- 学员主动要求系统训练 → 回到 P2/P3 重新开始
- 学员在持续创作中出现新的重大症候（L3）→ 建议回到 P2

### 迁移约束
- P0→P1→P2 单向递进（已有规则）
- P2→P3→P4 单向递进（新增规则）
- P4→P2 允许回退（重新开始循环）
- P4→P5 允许进入持续陪伴模式
- P5→P2/P3 允许回退（需要时）
- 不允许跳过（P2→P4 或 P2→P5 会被拒绝）''',
);

const Skill _outlineDiagnosis = Skill(
  meta: SkillMeta(
    id: 'outline-diagnosis',
    group: 'diagnosis',
    estimatedTokens: 4200,
  ),
  content: '''# SKILL: 大纲结构诊断

> **定位**: 教练如何诊断用户的小说大纲结构——判断大纲是否"有效"，定位核心病灶并引导改进。与 plot-design 的分工：plot-design 管"从零构建情节"，本 skill 管"已有大纲/故事结构如何诊断和改进"。
> **核心哲学**: 大纲是冲突的地图，不是事件的清单。
> **loadWhen**: 用户发送了完整大纲（>3章）/ 用户描述"故事大概" / 用户问"我的故事有什么问题"/"帮我看看大纲"/"大纲规划"等大纲相关请求
> **体积**: 约 4200 tokens

---

## 一、定位与激活条件

### 1.1 什么时候用本 skill

| 信号 | 含义 |
|------|------|
| 用户发送了完整大纲（≥3章） | → 使用 §三 五步诊断法 |
| 用户描述了"故事大概"（<3章的简述） | → 使用 §二 核心冲突诊断 |
| 用户问"我的故事有什么问题"/"帮我看看大纲" | → 使用 §三 五步诊断法 |
| 用户问"怎么写大纲"/"大纲怎么规划" | → 使用 §六 大纲构建方法论，不诊断 |
| 用户在聊天中提及"大纲""结构""规划""章节安排" | → 触发本 skill，询问用户想诊断还是构建 |
| plot-design 诊断出 P006/P015/P017 等结构性问题 | → 退回到大纲设计层，用本 skill 梳理整体结构 |

### 1.2 不用本 skill 的场景

- 用户在做生成式写作练习（N0-N2）→ 用 beginner-path
- 用户的文本问题只是句子/段落层面 → 用 technique-library
- 用户已经在执行具体的文本修改 → 不打断，等写完再诊断
- 用户正在从零构建（还没有故事）→ 先用 narrative-design + plot-design，等用户产出大纲后再用本 skill

### 1.3 核心哲学

> **大纲是冲突的地图，不是事件的清单。**

每一个章节都应该推进核心冲突。没有冲突的章节，是废章节。节奏的好坏不取决于事件的密度，而取决于冲突的密度。读者愿意读下去的唯一理由是"想知道接下来会发生什么"。

教练的任务不是帮作者设计剧情，而是诊断大纲是否"有效"。

---

## 二、核心冲突诊断（快速筛查）

### 2.1 冲突驱动原则

**核心问题：这一章，主角在争什么？**

**无效大纲示例：**
> 第1章：主角醒来，吃了早饭，去学校。
> 第2章：主角在学校上课，学习了魔法基础知识。
> 第3章：主角放学回家，路上遇到了一个神秘人。

**有效大纲示例：**
> 第1章：主角想要成为魔法师，但被告知他的灵脉破碎。
> 第2章：主角试图证明自己，但每次尝试都失败。
> 第3章：就在他准备放弃时，一个神秘人出现，告诉他有另一种可能。

**关键区别：** 每一章，主角都有一个"想要但得不到"的东西。

### 2.2 大纲有效性快速判定

一个大纲是否"有效"，看它是否满足以下至少 4 条：

1. **核心冲突清晰**：读者在前 3 章就知道主角在争什么
2. **冲突密度够**：没有连续超过 3 章的无冲突章节
3. **悬念有效**：至少有 3 个悬念，且每个悬念有明确的"悬念→揭晓"设计
4. **因果链清晰**：每个情节点都能追溯到前一个情节点
5. **人物立场鲜明**：每个主要角色都有明确的立场，且立场之间有冲突

如果低于 3 条 → 大纲需要重构，优先指出最关键的缺失。

---

## 三、五步诊断法（完整诊断流程）

### 第一步：判断大纲"有效性"

使用 §二 的 5 条标准逐条判断，给出评分（满足 n/5 条）。

### 第二步：识别核心病灶（按严重程度排序）

**1. 冲突缺失或虚浮（最严重）**
- 章节没有冲突，纯粹是"发生了什么"
- 冲突太弱，读者不关心
- 冲突可以轻易解决，没有"不得不"的张力
- 核心冲突直到很后面才出现

**对冲突缺失的引导：**
> "这一章的主角在争什么？他想要什么，而什么阻碍了他？"
> 如果答案是"没有什么冲突，他在做XX事"→ 这是废章节
> 建议：为每个章节设计一个"主角想要但得不到"的东西

**2. 节奏失衡**
- 铺垫太长，冲突来得太慢（超过 3 章无有效冲突）
- 冲突太密集，没有喘息空间（全程高能 = 没有高能）
- 高潮和低谷分布不均
- 没有"章末悬念"，读者可以随时停下来

**对节奏失衡的引导：**
> "如果删掉这章，故事会断裂吗？"
> 如果答案是"不会"→ 这是过渡章节，需要增加冲突或压缩
> 建议：把铺垫转化为冲突——让主角在铺垫阶段有一个小目标受阻

**3. 悬念失效**
- 悬念太多，每个都浅尝辄止
- 悬念揭晓太早，后续缺乏新的悬念
- 悬念与核心冲突无关
- 没有"章内悬念"（每章结尾的钩子）

**对悬念失效的引导：**
> "读者在这一章结尾时，最想知道什么？"
> 如果你自己回答不上来 → 悬念设计失败
> 建议：每个章节只保留 1 个主要悬念，揭晓后立刻接上新的悬念

**4. 因果链断裂**
- 情节点之间没有必然联系，"因为 A 所以 B"不成立
- 角色决定缺乏充分动机
- 为了剧情强行转折

**对因果链断裂的引导：**
> "如果删掉这个情节点，后续会受影响吗？"
> 如果答案是"不会"→ 这是废情节，需要与核心冲突挂钩
> 建议：每个情节点都必须追溯到核心冲突——要么推进冲突，要么揭示冲突

**5. 人物立场模糊**
- 主角没有明确的立场
- 反派立场不鲜明（纯粹是"坏"）
- 配角缺乏独立立场（工具人）

**对人物立场模糊的引导：**
> "这个角色最在乎什么？他愿意为此牺牲什么？"
> 如果答案是"他没什么特别在乎的"→ 这是工具人
> 建议：给每个主要角色设计一个"核心立场"和"底线"

### 第三步：给出针对性方案

针对第二步识别的每个病灶，给改进方向——给方法，不给具体剧情。

### 第四步：提供验证标准

诊断结束后提供用户可以自查的标准，例如：
> "改完后，你应该能用一句话描述每一章：'主角XX想要XX，但被XX阻碍'。"

### 第五步：收束

如果用户接受诊断并开始修改 → 收束，让他去写。
如果有多个病灶 → 只聚焦最重要的 1-2 个，不要一次给太多。

---

## 四、诊断维度详解

### 维度 1：核心冲突清晰度（最重要，权重 30%）

**判断问题：**
- 读者在前 3 章就知道主角在争什么吗？
- 核心冲突是什么？对抗力量是什么？
- 主角的目标和阻碍是什么？

**病灶表现：** 核心冲突太晚出现（前 5 章还在铺垫）、冲突太模糊、冲突太简单没有"不得不"的张力

### 维度 2：冲突密度（权重 25%）

**判断问题：**
- 连续无冲突章节最多有多少章？
- 每个冲突的解决是否带来局面变化？
- 是否有过长铺垫（>3 章）？

**病灶表现：** 连续 3 章以上无有效冲突、冲突解决后没有新冲突接上、铺垫与冲突比例失衡

### 维度 3：因果链清晰度（权重 20%）

**判断问题：**
- 每个情节点能追溯到核心冲突吗？
- 角色决定有充分动机吗？
- 情节之间有必然联系吗？

**有效因果示例：** 因为 A 所以 B → 因为 B 所以 C → 因为 C 所以 D

**无效因果：** B 在 A 之后发生，但 A 不是 B 的原因。

**因果链检测法：** 从最后一个情节点往前推，问"为什么"，如果能追溯到核心冲突 → 有效。

### 维度 4：悬念有效性（权重 15%）

**判断问题：**
- 每章结尾的悬念是什么？
- 悬念与核心冲突有关吗？
- 揭晓悬念后是否有新悬念接上？

**悬念类型：** 核心悬念（贯穿全书）、章节悬念（每章结尾）、小悬念（具体情节疑问）

**规则：** 每章最多 1 个主要悬念、悬念必须与核心冲突有关、揭晓后必须有新悬念接上、不要在一个悬念还没揭晓时引入太多新悬念

### 维度 5：节奏设计（权重 10%）

**核心公式：** 好节奏 = 冲突密度 × 变化幅度

**节奏类型：** 快节奏（冲突密集变化大，适合爽文/冒险）、慢节奏（冲突稀疏但深刻，适合文学/情感）、张弛有度（冲突-缓冲交替，适合大多数类型）

**禁忌：** 超过 3 章的纯粹铺垫、全程高能（没有低谷 = 没有高潮）、没有变化的重复冲突

---

## 五、回应格式（使用 [YS_OUTLINE] 标记）

每次大纲诊断的完整回应应遵循以下格式：

### 5.1 自然语言部分（必含）
1. **有效性判断**（1 句话）：满足 X/5 条，核心问题是...
2. **核心病灶定位**（1-2 句话）：最严重的问题是什么
3. **具体例证**（引用大纲原文或用户描述）
4. **原理说明**（为什么这是问题）
5. **改进方向**（给方法，不给具体剧情）
6. **验证标准**（改完后如何自检）

### 5.2 结构化输出（可选）
当用户要求结构化结果时，使用以下标记块：

```
[YS_OUTLINE]
{
  "diagnosis": {
    "overallScore": 75,
    "validityCount": 3,
