  },
  "nodes": [
    { "title": "第1章：灵脉测试", "depth": 0, "conflict": "主角想要通过测试，但被告知灵脉破碎", "hasSuspense": true },
    { "title": "第2章：被退学", "depth": 0, "conflict": "主角试图证明自己有价值，但每次尝试都失败", "hasSuspense": true },
    { "title": "第3章：神秘人的提议", "depth": 0, "conflict": "主角要决定是否相信这个来路不明的机会", "hasSuspense": true }
  ]
}
[/YS_OUTLINE]
```

